import sys,re
def strip(t):
    # remove /-- ... -/ and /-! ... -/ and /- ... -/ (nested), and -- line comments
    out=[];i=0;n=len(t);depth=0
    while i<n:
        if t.startswith('/-',i):
            depth+=1;i+=2;continue
        if depth>0:
            if t.startswith('-/',i): depth-=1;i+=2;continue
            i+=1;continue
        if t.startswith('--',i):
            j=t.find('\n',i); i = n if j<0 else j; continue
        out.append(t[i]);i+=1
    s=''.join(out)
    # normalize whitespace per token
    return re.sub(r'\s+',' ',s)
a=strip(open(sys.argv[1]).read()); b=strip(open(sys.argv[2]).read())
import difflib
at=a.split(' '); bt=b.split(' ')
sm=difflib.SequenceMatcher(None,at,bt,autojunk=False)
for op,i1,i2,j1,j2 in sm.get_opcodes():
    if op!='equal':
        print(op, '| OLD:', ' '.join(at[max(0,i1-8):i2+3]), '\n   | NEW:', ' '.join(bt[max(0,j1-8):j2+3]),'\n')
EOF
python3 -I $R4/strip.py $R4/hp_head.lean $R4/hp_work.lean

